#!/usr/bin/env bash
# List anything left behind after `cdk destroy`, by name prefix and by tag.
# Read-only: it never deletes. Prints counts and names; never prints account IDs.
# Usage: [ECOM_CONFIG=config/<profile>.json] scripts/check_residuals.sh [prefix] [region]
set -uo pipefail
source "$(dirname "$0")/lib/prefix.sh"
P="${1:-$PROJECT}"; R="${2:-${AWS_REGION:-us-east-1}}"; export AWS_REGION="$R"
q() { local v="${2:-}"; [ -z "$v" ] || [ "$v" = "None" ] && v="<none>"; printf '%-28s %s\n' "$1" "$v"; }
q "region" "$R"
q "cfn stacks" "$(aws cloudformation list-stacks --query "StackSummaries[?starts_with(StackName,'$P') && StackStatus!='DELETE_COMPLETE'].[StackName,StackStatus]" --output text | tr '\n' ' ')"
q "tagged resources" "$(aws resourcegroupstaggingapi get-resources --tag-filters Key=Project,Values=ecommerce-graviton-cicd --query 'ResourceTagMappingList[].ResourceARN' --output text | sed -E 's/[0-9]{12}/<ACCOUNT_ID>/g' | tr '\t' '\n' | sed 's/^/\n    /' | tr -d '\n')"
q "s3 buckets" "$(aws s3api list-buckets --query "Buckets[?starts_with(Name,'$P')].Name" --output text)"
q "log groups" "$(aws logs describe-log-groups --query "logGroups[?contains(logGroupName,'$P')].logGroupName" --output text)"
q "ecr repos" "$(aws ecr describe-repositories --query "repositories[?starts_with(repositoryName,'$P')].repositoryName" --output text 2>/dev/null)"
q "lambda functions" "$(aws lambda list-functions --query "Functions[?starts_with(FunctionName,'$P')].FunctionName" --output text)"
q "iam roles" "$(aws iam list-roles --query "Roles[?starts_with(RoleName,'$P')].RoleName" --output text)"
q "iam policies (local)" "$(aws iam list-policies --scope Local --query "Policies[?starts_with(PolicyName,'$P')].PolicyName" --output text)"
q "rds instances" "$(aws rds describe-db-instances --query "DBInstances[?starts_with(DBInstanceIdentifier,'$P')].DBInstanceIdentifier" --output text)"
q "rds snapshots (manual)" "$(aws rds describe-db-snapshots --snapshot-type manual --query "DBSnapshots[?starts_with(DBSnapshotIdentifier,'$P')].DBSnapshotIdentifier" --output text)"
q "rds snapshots (auto)" "$(aws rds describe-db-snapshots --snapshot-type automated --query "DBSnapshots[?starts_with(DBInstanceIdentifier,'$P')].DBSnapshotIdentifier" --output text)"
q "rds param groups" "$(aws rds describe-db-parameter-groups --query "DBParameterGroups[?starts_with(DBParameterGroupName,'$P')].DBParameterGroupName" --output text)"
q "rds subnet groups" "$(aws rds describe-db-subnet-groups --query "DBSubnetGroups[?starts_with(DBSubnetGroupName,'$P')].DBSubnetGroupName" --output text)"
q "elasticache groups" "$(aws elasticache describe-replication-groups --query "ReplicationGroups[?starts_with(ReplicationGroupId,'$P')].ReplicationGroupId" --output text)"
q "elasticache snapshots" "$(aws elasticache describe-snapshots --query "Snapshots[?starts_with(SnapshotName,'$P')].SnapshotName" --output text)"
q "elasticache subnet groups" "$(aws elasticache describe-cache-subnet-groups --query "CacheSubnetGroups[?starts_with(CacheSubnetGroupName,'$P')].CacheSubnetGroupName" --output text)"
q "opensearch domains" "$(aws opensearch list-domain-names --query "DomainNames[?starts_with(DomainName,'$P')].DomainName" --output text)"
q "efs file systems" "$(aws efs describe-file-systems --query "FileSystems[?starts_with(Name||'','$P')].FileSystemId" --output text)"
q "ecs clusters" "$(aws ecs list-clusters --query "clusterArns[?contains(@,'$P')]" --output text | sed -E 's/[0-9]{12}/<ACCOUNT_ID>/g')"
q "ecs task def families" "$(aws ecs list-task-definition-families --family-prefix "$P" --status ACTIVE --query families --output text)"
q "vpcs" "$(aws ec2 describe-vpcs --filters Name=tag:Project,Values=ecommerce-graviton-cicd --query 'Vpcs[].VpcId' --output text)"
q "nat gateways (not deleted)" "$(aws ec2 describe-nat-gateways --filter Name=tag:Project,Values=ecommerce-graviton-cicd --query "NatGateways[?State!='deleted'].NatGatewayId" --output text)"
q "elastic ips" "$(aws ec2 describe-addresses --filters Name=tag:Project,Values=ecommerce-graviton-cicd --query 'Addresses[].AllocationId' --output text)"
q "load balancers" "$(aws elbv2 describe-load-balancers --query "LoadBalancers[?starts_with(LoadBalancerName,'$P')].LoadBalancerName" --output text)"
# Target group names are generated by CloudFormation (no project prefix), so look them up by tag.
q "target groups (tagged)" "$(aws resourcegroupstaggingapi get-resources --resource-type-filters elasticloadbalancing:targetgroup --tag-filters Key=Project,Values=ecommerce-graviton-cicd --query 'ResourceTagMappingList[].ResourceARN' --output text | sed -E 's/[0-9]{12}/<ACCOUNT_ID>/g')"
q "secrets" "$(aws secretsmanager list-secrets --include-planned-deletion --query "SecretList[?starts_with(Name,'$P')].[Name,DeletedDate]" --output text | tr '\n' ' ')"
q "ssm parameters" "$(aws ssm describe-parameters --parameter-filters Key=Name,Option=BeginsWith,Values=/$P --query 'Parameters[].Name' --output text)"
q "sqs queues" "$(aws sqs list-queues --queue-name-prefix "$P" --query QueueUrls --output text | sed -E 's/[0-9]{12}/<ACCOUNT_ID>/g')"
q "sns topics" "$(aws sns list-topics --query "Topics[?contains(TopicArn,':$P')].TopicArn" --output text | sed -E 's/[0-9]{12}/<ACCOUNT_ID>/g')"
q "event buses" "$(aws events list-event-buses --name-prefix "$P" --query 'EventBuses[].Name' --output text)"
q "dynamodb tables" "$(aws dynamodb list-tables --query "TableNames[?starts_with(@,'$P')]" --output text)"
q "codebuild projects" "$(aws codebuild list-projects --query "projects[?starts_with(@,'$P')]" --output text)"
q "codepipelines" "$(aws codepipeline list-pipelines --query "pipelines[?starts_with(name,'$P')].name" --output text)"
q "cloudwatch alarms" "$(aws cloudwatch describe-alarms --query "MetricAlarms[?starts_with(AlarmName,'$P')].AlarmName" --output text | wc -w | tr -d ' ') named-prefix"
q "kms keys tagged" "$(for k in $(aws kms list-keys --query 'Keys[].KeyId' --output text); do aws kms list-resource-tags --key-id "$k" --query "Tags[?TagKey=='Project' && TagValue=='ecommerce-graviton-cicd']" --output text 2>/dev/null | grep -q . && echo "$k:$(aws kms describe-key --key-id "$k" --query KeyMetadata.KeyState --output text)"; done | tr '\n' ' ')"
q "api gateways" "$(aws apigateway get-rest-apis --query "items[?starts_with(name,'$P')].name" --output text) $(aws apigatewayv2 get-apis --query "Items[?starts_with(Name,'$P')].Name" --output text)"
